{
  "name": "Ark Metrica步进电机线性位移控制器",
  "name_en": "Ark Metrica Stepper Motor Linear Motion Controller",
  "manufacturer": "Ark Metrica",
  "description": "用于控制步进电机驱动的线性位移机构或位移台。该设备通过串口/VISA通信，支持连接识别、速度与加速度设置、回零、按目标位置移动、位置读取以及急停，适合实验中的样品或探头直线定位任务。",
  "description_en": "A stepper-motor-based linear motion controller for a linear actuator or positioning stage. It communicates over serial/VISA and supports device identification, speed and acceleration settings, homing, moving to a target position, position readback, and emergency stop for laboratory sample or probe positioning tasks.",
  "tag_hints": [
    "stepper motor control",
    "linear actuator",
    "positioning stage",
    "homing",
    "serial motion controller",
    "emergency stop",
    "position readback"
  ],
  "actions": [
    {
      "action_name": "auto-address",
      "description": "获取/设置设备资源地址",
      "description_en": "Get/set the device resource address."
    },
    {
      "action_name": "auto-resource_kwargs",
      "description": "获取资源连接参数",
      "description_en": "Get the resource connection parameters."
    },
    {
      "action_name": "auto-motion_timeout",
      "description": "获取/设置运动超时时间",
      "description_en": "Get/set the motion timeout."
    },
    {
      "action_name": "auto-speed",
      "description": "获取/设置线性执行器速度",
      "description_en": "Get/set the linear actuator speed."
    },
    {
      "action_name": "auto-acceleration",
      "description": "获取/设置线性执行器加速度",
      "description_en": "Get/set the linear actuator acceleration."
    },
    {
      "action_name": "auto-mm_to_steps",
      "description": "将毫米距离转换为电机步数",
      "description_en": "Convert a distance in millimeters to motor steps."
    },
    {
      "action_name": "auto-steps_to_mm",
      "description": "将电机步数转换为毫米距离",
      "description_en": "Convert motor steps to a distance in millimeters."
    },
    {
      "action_name": "auto-idn",
      "description": "读取控制器身份信息",
      "description_en": "Read the controller identity string."
    },
    {
      "action_name": "auto-len_axes_mm",
      "description": "获取各轴的行程长度（毫米）",
      "description_en": "Get the travel length of each axis in millimeters."
    },
    {
      "action_name": "auto-goto",
      "description": "移动到目标位置",
      "description_en": "Move to the target position."
    },
    {
      "action_name": "auto-home",
      "description": "执行回零/归位",
      "description_en": "Perform a homing operation."
    },
    {
      "action_name": "auto-estop",
      "description": "执行急停",
      "description_en": "Request an emergency stop."
    },
    {
      "action_name": "auto-get_position",
      "description": "读取当前位置（毫米）",
      "description_en": "Read the current position in millimeters."
    }
  ]
}

